// Forward the exact body Calendly signed, with its signature, so the agent can verify it.
const crypto = require('crypto');
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  let raw = '';
  if (item.binary && item.binary.data) {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    raw = buf.toString('utf8');
  } else {
    raw = JSON.stringify(item.json.body ?? {});
  }
  const headers = item.json.headers ?? {};
  const body = JSON.stringify({ token: String(item.json.params?.token ?? ''), raw, signature: String(headers['calendly-webhook-signature'] ?? '') });
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto.createHmac('sha256', $env.PLATFORM_HMAC_SECRET).update(`${timestamp}.${body}`).digest('hex');
  out.push({ json: { timestamp, body, signature } });
}
return out;
